// --- Physics (movement + wall/paddle/brick bounces) -------------------------

// The longest distance the ball may travel per physics sub-step. Smaller than
// the thinnest obstacle (PADDLE_H = 12) so a fast ball can never jump over a
// brick or the paddle between two collision tests, whatever the level and dt.
const SUB_STEP = 6;

// True if the ball's swept box (previous position -> current position) overlaps
// the brick: the continuous version of `collides`, immune to tunneling.
function sweptOverlaps(ball, brick, prevX, prevY) {
  const minX = Math.min(prevX, ball.x) - ball.r;
  const maxX = Math.max(prevX, ball.x) + ball.r;
  const minY = Math.min(prevY, ball.y) - ball.r;
  const maxY = Math.max(prevY, ball.y) + ball.r;
  return (
    maxX > brick.x &&
    minX < brick.x + brick.w &&
    maxY > brick.y &&
    minY < brick.y + brick.h
  );
}

// True if the ball's box already overlapped the brick's range along one axis
// at the start of the sub-step.
function alreadyInside(v, min, max, lo, hi) {
  return min < hi && max > lo;
}

// Entry time of the ball's box into the brick's range along one axis during
// the sub-step. -Infinity = already inside at the start; Infinity = never
// (velocity is zero and the box is outside).
function entryTime(v, lo, hi, prevMin, prevMax) {
  if (alreadyInside(v, prevMin, prevMax, lo, hi)) return -Infinity;
  if (v > 0) return (lo - prevMax) / v;
  if (v < 0) return (hi - prevMin) / v;
  return Infinity;
}

// Resolves one brick bounce: flips the axis of the face that was entered last
// (largest entry time), or both on an exact tie (corner), and pushes the ball
// out of the brick. At most one flip per axis per pass (seam guard).
function bounceBrick(ball, brick, prevX, prevY) {
  const tX = entryTime(ball.vx, brick.x, brick.x + brick.w, prevX - ball.r, prevX + ball.r);
  const tY = entryTime(ball.vy, brick.y, brick.y + brick.h, prevY - ball.r, prevY + ball.r);

  if (tX === tY) {
    // Corner: both faces entered at the same time -> both axes flip.
    if (ball.vx !== 0) ball.vx = -ball.vx;
    if (ball.vy !== 0) ball.vy = -ball.vy;
    if (ball.vx !== 0) ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
    if (ball.vy !== 0) ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
  } else if (tX > tY) {
    if (ball.vx !== 0) ball.vx = -ball.vx;
    ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
  } else {
    if (ball.vy !== 0) ball.vy = -ball.vy;
    ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
  }
}
