// --- Rendering (DOM) -------------------------------------------------------

// Main render loop: draws the field. Collisions, scoring and level flow live
// in the pure `step()` / `boot()`; nothing here changes the game state except
// drawing helpers.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only — collision, destruction and scoring happen in
  // `step()` so they are testable without a DOM.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

