// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// The longest distance the ball may travel per physics sub-step. Smaller than
// the thinnest obstacle it can hit (PADDLE_H = 12), so a fast ball can never
// jump over a brick or the paddle between two collision tests, whatever the
// level and the dt (no tunneling, no dependence on the frame rate).
const SUB_STEP = 6;

// True if the ball's swept box (previous position -> current position)
// overlaps the brick: the continuous version of `collides`, immune to
// tunneling when the ball covers more than the brick height in one step.
function sweptOverlaps(ball, brick, prevX, prevY) {
  return (
    Math.max(prevX, ball.x) + ball.r > brick.x &&
    Math.min(prevX, ball.x) - ball.r < brick.x + brick.w &&
    Math.max(prevY, ball.y) + ball.r > brick.y &&
    Math.min(prevY, ball.y) - ball.r < brick.y + brick.h
  );
}

// Entry time of the ball's box into the brick's range along one axis during
// the sub-step, in seconds. -Infinity: already inside at the start of the
// step; Infinity: never (velocity is zero and the box is outside).
function entryTime(v, lo, hi, prevMin, prevMax) {
  if (prevMin < hi && prevMax > lo) return -Infinity; // already inside
  if (v > 0) return (lo - prevMax) / v;
  if (v < 0) return (hi - prevMin) / v;
  return Infinity;
}

// Resolves one brick bounce. The face hit is the axis entered LAST (largest
// entry time): a ball climbing from below entered the brick's y-range later
// than its x-range, so it hit a horizontal face and vy flips. An exact tie is
// a corner: both axes flip. The ball is pushed out of the brick on the side
// it came from (velocity direction), so it never starts the next step
// overlapping the brick it just hit.
function bounceBrick(ball, brick, prevX, prevY) {
  const tX = entryTime(ball.vx, brick.x, brick.x + brick.w, prevX - ball.r, prevX + ball.r);
  const tY = entryTime(ball.vy, brick.y, brick.y + brick.h, prevY - ball.r, prevY + ball.r);

  if (tX === tY) {
    // Corner: both faces entered at the same time -> both axes flip.
    if (ball.vx !== 0) ball.vx = -ball.vx;
    if (ball.vy !== 0) ball.vy = -ball.vy;
    if (ball.vx !== 0) ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
    if (ball.vy !== 0) ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
  } else if (tX > tY) {
    if (ball.vx !== 0) ball.vx = -ball.vx;
    ball.x = ball.vx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
  } else {
    if (ball.vy !== 0) ball.vy = -ball.vy;
    ball.y = ball.vy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (scoring included). The frame is split
// into sub-steps so the detection is swept: a fast ball can no longer cross a
// brick or the paddle between two tests. The bricks are destroyed and scored
// on every overlapped brick, but the ball bounces only once, against the face
// entered last (one rebound per pass and per axis: a grid-seam straddle never
// double-flips).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.ceil(distance / SUB_STEP));
  const sdt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    const prevX = ball.x;
    const prevY = ball.y;

    ball.x += ball.vx * sdt;
    ball.y += ball.vy * sdt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle: the ball is caught when its bottom edge crosses the paddle top
    // during this sub-step (swept, so no tunneling at high speed) and its box
    // overlaps the paddle's x-range (box, not center: edge hits count).
    if (
      ball.vy > 0 &&
      prevY + ball.r <= paddle.y &&
      ball.y + ball.r >= paddle.y &&
      ball.x + ball.r > paddle.x &&
      ball.x - ball.r < paddle.x + paddle.w
    ) {

[149 more lines in file. Use offset=258 to continue.]

      ball.y = paddle.y - ball.r;
      // The rebound angle depends on where the paddle was hit, clamped to the
      // paddle width. A minimum horizontal component keeps every trajectory
      // playable (no dead vertical loop on an exact center hit). The two
      // components are derived from the same angle, so the level speed is
      // preserved exactly (no acceleration or decay across exchanges).
      const half = paddle.w / 2;
      const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + half)) / half));
      const speed = ballSpeed(state.level);
      let dx = 0.6 * hit;
      if (Math.abs(dx) < 0.1) dx = (dx < 0 ? -1 : 1) * 0.1;
      ball.vx = speed * dx;
      ball.vy = -speed * Math.sqrt(1 - dx * dx);
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: swept detection, scoring, then a single bounce (largest entry
    // time wins; an exact tie between two bricks keeps the first one).
    let hitBrick = null;
    let hitKey = -Infinity;
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (!sweptOverlaps(ball, brick, prevX, prevY)) continue;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      const key = Math.max(
        entryTime(ball.vx, brick.x, brick.x + brick.w, prevX - ball.r, prevX + ball.r),
        entryTime(ball.vy, brick.y, brick.y + brick.h, prevY - ball.r, prevY + ball.r)
      );
      if (key >= hitKey) {
        hitKey = key;
        hitBrick = brick;
      }
    }
    if (hitBrick) bounceBrick(ball, hitBrick, prevX, prevY);

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop: draws the field. Collisions, scoring and level flow live
// in the pure `step()` / `boot()`; nothing here changes the game state except
// drawing helpers.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only — collision, destruction and scoring happen in
  // `step()` so they are testable without a DOM.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}
